using System;using System.Linq;using UnityEngine;
public static class InspectExplorationRuntime {public static object Main(){var world=UnityEngine.Object.FindAnyObjectByType<ExplorationWorld>();return new{playing=Application.isPlaying,map=world.Map!=null,loaded=world.LoadedTiles,trees=world.GetComponentsInChildren<ForestTreeWind>().Length,roadSoils=world.GetComponentsInChildren<RainSoakedRoad>().Length,lakes=world.GetComponentsInChildren<WaterVolume>().Length,car=world.vehicle.position.ToString(),profile=world.weather.profile.name,oldRoots=world.replacedRoots.Count(r=>r.activeSelf)};}}
